'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaultConfig={name:'APARK � EXPERIENCIA ARQUITECTONICA',count:18,numbering:'reference',top:180,bottom:1208,levels:{}};
let config;try{config={...defaultConfig,...JSON.parse(localStorage.getItem('nexo-project-v1')||'null')}}catch{config={...defaultConfig}};
config.count=Math.max(1,Math.min(40,Number(config.count)||18));config.levels=config.levels||{};
let selected=null,zoomed=false,tourTimer=null,tourActive=false,activeTab='facade',db=null,currentAssetFloor=1,pendingFiles={};
const stage=$('#stage'),world=$('#world'),overlay=$('#overlay');let base={scale:1,x:0,y:0},hovered=null;
function openDB(){return new Promise(resolve=>{if(!window.indexedDB)return resolve(null);const req=indexedDB.open('nexo-project-assets',1);req.onupgradeneeded=()=>req.result.createObjectStore('assets');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)})}
const dbReady=openDB().then(v=>db=v);
function assetGet(key){return new Promise(resolve=>{if(!db)return resolve(null);const req=db.transaction('assets').objectStore('assets').get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null)})}
function assetPut(key,value){return new Promise((resolve,reject)=>{if(!db)return reject(new Error('No se pudo guardar el archivo en este navegador.'));const tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(new Error('No hay espacio suficiente para guardar los archivos.'))})}
function floorBox(n){const height=(config.bottom-config.top)/config.count;return{x:844,y:config.bottom-n*height,width:192,height}}
function floorName(n){return n===0?'Planta baja':`Nivel ${String(n).padStart(2,'0')}`}
function allLevels(){return Array.from({length:config.count},(_,i)=>config.count-i)}
function buildFloors(){overlay.replaceChildren();$('#floorList').replaceChildren();for(const n of allLevels()){const b=floorBox(n),rect=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [key,val] of Object.entries(b))rect.setAttribute(key,val);rect.dataset.floor=n;rect.classList.add('floor-zone');rect.setAttribute('role','button');rect.setAttribute('tabindex','0');rect.setAttribute('aria-label',`Seleccionar ${floorName(n)}`);rect.addEventListener('click',()=>selectFloor(n));rect.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectFloor(n)}});rect.addEventListener('pointerenter',()=>showHover(n));rect.addEventListener('pointerleave',hideHover);overlay.append(rect);const button=document.createElement('button');button.className='rail-level';button.dataset.floor=n;button.textContent=String(n).padStart(2,'0');button.setAttribute('aria-label',`Seleccionar ${floorName(n)}`);button.addEventListener('click',()=>selectFloor(n));$('#floorList').append(button)}
const pb=document.createElementNS('http://www.w3.org/2000/svg','rect');Object.entries({x:844,y:config.bottom,width:192,height:1282-config.bottom}).forEach(([k,v])=>pb.setAttribute(k,v));pb.classList.add('floor-zone');pb.dataset.floor=0;pb.setAttribute('role','button');pb.setAttribute('tabindex','0');pb.setAttribute('aria-label','Seleccionar planta baja');pb.addEventListener('click',()=>selectFloor(0));pb.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectFloor(0)}});overlay.append(pb);$('#projectLabel').textContent=config.name;$('.reference-note').hidden=config.numbering==='confirmed';updateSelection()}
function updateSelection(){ $$('[data-floor]').forEach(el=>{const match=Number(el.dataset.floor)===selected;el.classList.toggle('selected',match);el.setAttribute('aria-pressed',String(match))});}
function layout(){const w=stage.clientWidth,h=stage.clientHeight;base.scale=Math.max(w/2048,h/1365);base.x=(w-2048*base.scale)/2;base.y=(h-1365*base.scale)/2;camera(zoomed);if(hovered!==null)showHover(hovered);if($('#detailDialog').open&&activeTab==='facade')renderDetail()}
function camera(zoom=false){let s=base.scale,x=base.x,y=base.y;if(zoom&&selected!==null){const b=selected===0?{x:844,y:config.bottom,width:192,height:1282-config.bottom}:floorBox(selected);s*=window.innerWidth<640?1.65:2.25;const targetX=stage.clientWidth*(window.innerWidth<640?.43:.43),targetY=stage.clientHeight*(window.innerWidth<640?.37:.48);x=targetX-(b.x+b.width/2)*s;y=targetY-(b.y+b.height/2)*s;}world.style.transform=`translate(${x}px,${y}px) scale(${s})`}
function showHover(n){if(zoomed)return;hovered=n;const box=floorBox(n),label=$('#hoverLabel');label.textContent=floorName(n);label.style.left=`${Math.min(stage.clientWidth-110,base.x+(box.x+box.width)*base.scale+12)}px`;label.style.top=`${base.y+(box.y+box.height/2)*base.scale-16}px`;label.hidden=false}
function hideHover(){hovered=null;$('#hoverLabel').hidden=true}
function selectFloor(n,{keepTour=false}={}){if(!keepTour)stopTour();selected=Math.max(0,Math.min(config.count,n));document.body.classList.add('exploring');$('#floorPanel').hidden=false;$('#general').classList.remove('active');$('#explore').classList.add('active');$('#floorNumber').textContent=selected===0?'PB':String(selected).padStart(2,'0');const data=config.levels[selected]||{};$('#floorTitle').textContent=data.title||'Una mirada desde aqu�.';$('#floorDescription').textContent=data.description||'Ac�rcate a la fachada y descubre este nivel.';$('#levelPosition').textContent=`${selected===0?'PB':String(selected).padStart(2,'0')} / ${config.count}`;$('#prevFloor').disabled=selected===0;$('#nextFloor').disabled=selected===config.count;$('#instruction').textContent='Selecciona otro nivel o descubre el espacio';$('#viewLabel span').textContent=selected===0?'PB':String(selected).padStart(2,'0');updateSelection();hideHover();if(zoomed)camera(true)}
function resetView(){stopTour();selected=null;zoomed=false;document.body.classList.remove('exploring');$('#floorPanel').hidden=true;$('#viewLabel').hidden=true;$('#general').classList.add('active');$('#explore').classList.remove('active');$('#instruction').textContent='Selecciona un nivel sobre la torre';updateSelection();camera(false)}
function stopTour(){clearInterval(tourTimer);tourTimer=null;tourActive=false;$('#playIcon').textContent='?';$('#tourLabel').textContent='Recorrer torre';$('#tour').setAttribute('aria-label','Iniciar recorrido autom�tico')}
function startTour(){if(tourActive)return stopTour();zoomed=false;camera(false);tourActive=true;$('#playIcon').textContent='?';$('#tourLabel').textContent='Pausar recorrido';$('#tour').setAttribute('aria-label','Pausar recorrido autom�tico');let n=1;selectFloor(n,{keepTour:true});tourTimer=setInterval(()=>{n++;if(n>config.count){stopTour();return}selectFloor(n,{keepTour:true})},1800)}
function showToast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
function openDialog(id){stopTour();hideHover();const dialog=$('#'+id);if(!dialog.open)dialog.showModal()}
function openDetail(){if(selected===null)return;stopTour();zoomed=true;camera(true);$('#viewLabel').hidden=false;activeTab='facade';openDialog('detailDialog');renderDetail()}
let assetUrl=null,renderToken=0;
async function renderDetail(){const token=++renderToken;const n=selected??1,data=config.levels[n]||{};$('#detailTitle').textContent=floorName(n);$('#detailKicker').textContent=data.title||'TORRE PRINCIPAL';$('#detailSub').textContent=data.description||'Cada nivel, una nueva perspectiva.';$('#detailCounter').textContent=`${n===0?'PB':String(n).padStart(2,'0')} / ${config.count}`;$('#detailPrev').disabled=n===0;$('#detailNext').disabled=n===config.count;$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===activeTab)));const content=$('#detailContent');content.replaceChildren();if(assetUrl){URL.revokeObjectURL(assetUrl);assetUrl=null}if(activeTab==='facade'){const b=n===0?{x:844,y:config.bottom,width:192,height:1282-config.bottom}:floorBox(n),s=Math.min(content.clientWidth/420,content.clientHeight/190);const div=document.createElement('div');div.className='detail-facade';div.style.setProperty('--detail-w',`${2048*s}px`);div.style.setProperty('--detail-h',`${1365*s}px`);div.style.setProperty('--detail-x',`${content.clientWidth/2-(b.x+b.width/2)*s}px`);div.style.setProperty('--detail-y',`${content.clientHeight/2-(b.y+b.height/2)*s}px`);content.append(div);const caption=document.createElement('span');caption.className='detail-caption';caption.textContent=`${floorName(n)} � Detalle de fachada`;content.append(caption);return}await dbReady;const asset=await assetGet(`${n}-${activeTab}`);if(token!==renderToken)return;if(asset){assetUrl=URL.createObjectURL(asset);const img=document.createElement('img');img.className='detail-asset';img.src=assetUrl;img.alt=`${activeTab==='plan'?'Planta':'Interior'} de ${floorName(n)}`;content.append(img)}else{const empty=document.createElement('div');empty.className='empty-state';const symbol=document.createElement('span');symbol.className='empty-symbol';symbol.textContent=activeTab==='plan'?'?':'?';const h=document.createElement('h3');h.textContent=activeTab==='plan'?'La planta de este nivel':'El interior de este nivel';const p=document.createElement('p');p.textContent=activeTab==='plan'?'Agrega la planta real para explorar su distribuci�n y continuar el recorrido.':'Agrega un render interior de este nivel para descubrir sus espacios.';const button=document.createElement('button');button.textContent='Agregar archivo del proyecto';button.addEventListener('click',()=>{$('#detailDialog').close();openSettings(n)});empty.append(symbol,h,p,button);content.append(empty)}}
async function loadFloorFields(n){currentAssetFloor=Number(n);pendingFiles={};const data=config.levels[n]||{};$('#customTitle').value=data.title||'';$('#customDescription').value=data.description||'';$('#planFile').value='';$('#interiorFile').value='';await dbReady;for(const [tab,el]of[['plan','#planStatus'],['interior','#interiorStatus']]){const asset=await assetGet(`${n}-${tab}`);$(el).textContent=asset?'Archivo guardado en este navegador':'JPG, PNG o WebP � hasta 15 MB'}}
function openSettings(n=selected??1){$('#projectName').value=config.name==defaultConfig.name?'':config.name;$('#floorCount').value=config.count;$('#numbering').value=config.numbering;$('#topBound').value=config.top;$('#bottomBound').value=config.bottom;$('#assetFloor').replaceChildren();for(let i=0;i<=config.count;i++){const opt=document.createElement('option');opt.value=i;opt.textContent=floorName(i);$('#assetFloor').append(opt)}$('#assetFloor').value=Math.min(n,config.count);$('#formError').textContent='';loadFloorFields($('#assetFloor').value);openDialog('settingsDialog')}
$('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();$('#formError').textContent='';const button=e.submitter;button.disabled=true;try{await dbReady;for(const [tab,file]of Object.entries(pendingFiles)){if(file.size>15*1024*1024)throw new Error('Cada imagen debe pesar menos de 15 MB.');if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw new Error('Usa im�genes JPG, PNG o WebP.');await assetPut(`${currentAssetFloor}-${tab}`,file)}config={...config,name:$('#projectName').value.trim()||defaultConfig.name,count:Number($('#floorCount').value),numbering:$('#numbering').value,top:Number($('#topBound').value),bottom:Number($('#bottomBound').value),levels:{...config.levels,[currentAssetFloor]:{title:$('#customTitle').value.trim(),description:$('#customDescription').value.trim()}}};localStorage.setItem('nexo-project-v1',JSON.stringify(config));buildFloors();if(selected!==null)selectFloor(Math.min(selected,config.count));layout();$('#settingsDialog').close();showToast('Proyecto actualizado en este navegador.')}catch(error){$('#formError').textContent=error.message||'No se pudieron guardar los cambios.'}finally{button.disabled=false}});
$('#assetFloor').addEventListener('change',e=>{config.levels[currentAssetFloor]={title:$('#customTitle').value.trim(),description:$('#customDescription').value.trim()};if(Object.keys(pendingFiles).length){e.target.value=currentAssetFloor;showToast('Guarda los archivos antes de cambiar de nivel.');return}loadFloorFields(e.target.value)});
for(const [input,tab,status]of[['#planFile','plan','#planStatus'],['#interiorFile','interior','#interiorStatus']])$(input).addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;pendingFiles[tab]=file;$(status).textContent=file.name});
$('#start').addEventListener('click',()=>selectFloor(Math.min(11,config.count)));$('#explore').addEventListener('click',()=>selectFloor(selected??Math.min(11,config.count)));$('#general').addEventListener('click',resetView);$('.brand').addEventListener('click',e=>{e.preventDefault();resetView()});$('#reset').addEventListener('click',resetView);$('#closePanel').addEventListener('click',resetView);$('#prevFloor').addEventListener('click',()=>selectFloor(selected-1));$('#nextFloor').addEventListener('click',()=>selectFloor(selected+1));$('#openFloor').addEventListener('click',openDetail);$('#tour').addEventListener('click',startTour);$('#materials').addEventListener('click',()=>openDialog('materialsDialog'));$('#settings').addEventListener('click',()=>openSettings());$('#closeDetail').addEventListener('click',()=>$('#detailDialog').close());$('#detailDialog').addEventListener('close',()=>{zoomed=false;camera(false);$('#viewLabel').hidden=true});$('#detailPrev').addEventListener('click',()=>{selectFloor(selected-1);renderDetail()});$('#detailNext').addEventListener('click',()=>{selectFloor(selected+1);renderDetail()});$$('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;renderDetail()}));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}));document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour()});document.addEventListener('keydown',e=>{if($('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Escape')resetView();if(selected!==null&&(e.key==='ArrowUp'||e.key==='ArrowDown')){e.preventDefault();selectFloor(selected+(e.key==='ArrowUp'?1:-1))}});new ResizeObserver(layout).observe(stage);buildFloors();layout();
